insert into public.categories (id, name, icon, color, sort_order, is_active) values
  ('sightseeing', '{"en":"Sightseeing","ko":"관광"}'::jsonb, '🏯', '#2D6CDF', 1, true),
  ('food', '{"en":"Food Trip","ko":"식도락"}'::jsonb, '🍜', '#E8772E', 2, true),
  ('culture', '{"en":"Culture","ko":"문화"}'::jsonb, '🏮', '#B83280', 3, true),
