  ('pack_dmz_east', 'course_pack', '{"en":"Mission Pack: DMZ & East Coast (coming soon)","ko":"미션팩: DMZ & 동해안 (예정)"}'::jsonb, 1.99, 'com.kotoventure.pack.dmzeast', 'pack_dmz_east', array[]::text[], false)
insert into public.courses (id, category_id, area, title, subtitle, description, region, entry, exit, nights, days, difficulty, party_fit, party_tips, start_budget, cover_bg, access, product_id, is_published, version, sort_order) values
  ('seoul-classic', 'sightseeing', 'seoul', '{"en":"Seoul Classic","ko":"서울 클래식"}'::jsonb, '{"en":"First-timer''s 5 nights / 7 days","ko":"첫 한국 여행 5박7일"}'::jsonb, '{"en":"Fly in from Australia and survive your first Seoul trip: get out of Incheon Airport, eat and sing in Myeongdong, deal with a sudden \"che-haet-da\" indigestion, then PLAN two free days yourself – opening days, weather, lunch, energy and the last subway all matter. Your early decisions (insurance, umbrella…) come back later!","ko":"호주에서 출발! 인천공항 탈출부터 명동, 노래방, 급체, 경복궁, 성수동, 남산, 한강까지."}'::jsonb, '{"en":"Seoul","ko":"서울"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, 5, 7, 1, '{"solo":5,"couple":5,"friends":5,"group":4}'::jsonb, '{"solo":{"en":"Stay near Myeongdong or Hongdae: hostels, single-portion restaurants and safe late-night streets.","ko":"명동이나 홍대 근처에 묵으세요. 호스텔, 1인분 식당, 밤늦게도 안전한 거리가 있어요."},"couple":{"en":"Book a hanbok set for two at Gyeongbokgung and catch sunset at N Seoul Tower.","ko":"경복궁에서 2인 한복 세트를 예약하고, N서울타워에서 노을을 보세요."},"friends":{"en":"Split taxis (max 4 per car), book a big noraebang room and try chimaek by the Han River.","ko":"택시는 나눠 타고(한 대 최대 4명), 노래방은 큰 방을 잡고, 한강에서 치맥을 즐겨 보세요."},"group":{"en":"Use airport limousine buses or a van taxi; reserve restaurants for 6+ in advance.","ko":"공항 리무진 버스나 대형 승합 택시를 이용하고, 6명 이상이면 식당을 미리 예약하세요."}}'::jsonb, 900000, 'palace', 'base', null, true, 5, 1),
  ('busan-food', 'food', 'gyeongsang', '{"en":"Busan Food Trail","ko":"부산 먹방 투어"}'::jsonb, '{"en":"Fly in, eat everything – 3 nights / 4 days","ko":"김해공항 입국 부산 먹방 3박4일"}'::jsonb, '{"en":"Land at Gimhae Airport, then eat your way through Jagalchi fish market, Gukje market hotteok, dwaeji gukbap, chimaek at Gwangalli beach under the drone show, and sleep in a giant jjimjilbang.","ko":"김해공항 입국 → 자갈치 → 국제시장 → 돼지국밥 → 감천 → 해운대 → 광안리 치맥 → 찜질방 → 김해공항."}'::jsonb, '{"en":"Busan","ko":"부산"}'::jsonb, '{"kind":"airport","code":"PUS","name":{"en":"Gimhae International Airport","ko":"김해국제공항"}}'::jsonb, '{"kind":"airport","code":"PUS","name":{"en":"Gimhae International Airport","ko":"김해국제공항"}}'::jsonb, 3, 4, 1, '{"solo":4,"couple":4,"friends":5,"group":5}'::jsonb, '{"solo":{"en":"Gukbap restaurants and market stalls are perfect for eating alone.","ko":"국밥집과 시장 노점은 혼밥하기에 딱 좋아요."},"couple":{"en":"Watch the Gwangalli drone light show (Saturday nights) from the beach.","ko":"토요일 밤 광안리 해변에서 드론 라이트쇼를 보세요."},"friends":{"en":"Share a big platter of raw fish at Jagalchi – more people, more dishes.","ko":"자갈치시장에서 큰 회 한 접시를 나눠 드세요. 인원이 많을수록 요리도 많아져요."},"group":{"en":"Busan seafood restaurants have big rooms for groups – book ahead on weekends.","ko":"부산 해산물 식당에는 단체석이 있어요. 주말에는 미리 예약하세요."}}'::jsonb, 600000, 'market', 'base', null, true, 6, 2),
  ('gyeongju-heritage', 'culture', 'gyeongsang', '{"en":"Gyeongju: Museum Without Walls","ko":"경주: 지붕 없는 박물관"}'::jsonb, '{"en":"Silla heritage & temple stay – 3 nights / 4 days","ko":"신라 천년 고도 3박4일"}'::jsonb, '{"en":"Land at Incheon, read the KTX map and buy your own train ticket to Gyeongju, sleep in a hanok, cycle between royal tombs and the 1,400-year-old Cheomseongdae observatory, bow at UNESCO-listed Bulguksa Temple and spend a night as a monk.","ko":"인천공항 → 서울역 KTX 발권 → 신경주 → 한옥 → 대릉원·첨성대 → 불국사 → 템플스테이 → 김해공항."}'::jsonb, '{"en":"Gyeongju, North Gyeongsang","ko":"경상북도 경주"}'::jsonb, '{"kind":"airport","code":"ICN","name":{"en":"Incheon International Airport","ko":"인천국제공항"}}'::jsonb, '{"kind":"airport","code":"PUS","name":{"en":"Gimhae International Airport","ko":"김해국제공항"}}'::jsonb, 3, 4, 2, '{"solo":5,"couple":4,"friends":3,"group":4}'::jsonb, '{"solo":{"en":"A temple stay is a peaceful, social way to travel alone.","ko":"템플스테이는 혼자 여행하기에 평화롭고, 사람들도 만날 수 있는 방법이에요."},"couple":{"en":"Night-time Donggung Palace & Wolji Pond reflections are the most romantic view in Gyeongju.","ko":"밤의 동궁과 월지 반영은 경주에서 가장 낭만적인 풍경이에요."},"friends":{"en":"Rent bikes together – the heritage sites are flat and close to each other.","ko":"함께 자전거를 빌리세요. 유적지는 평탄하고 서로 가까워요."},"group":{"en":"City-tour buses and private hanok houses suit families and groups.","ko":"시티투어 버스와 독채 한옥은 가족·단체에 잘 맞아요."}}'::jsonb, 500000, 'temple', 'base', null, true, 5, 3),
  ('jeju-adventure', 'adventure', 'jeju', '{"en":"Jeju Volcano Quest","ko":"제주 화산섬 탐험"}'::jsonb, '{"en":"Hike, drive & survive a typhoon – 4 nights / 5 days","ko":"한라산·성산일출봉 4박5일"}'::jsonb, '{"en":"Land at Jeju International Airport, rent a car (with your International Driving Permit!), summit Hallasan – Korea''s highest mountain – watch sunrise at Seongsan Ilchulbong, meet the haenyeo women divers and ride out a typhoon.","ko":"제주공항 → 렌터카 → 한라산 등반 → 성산일출봉 → 해녀 → 올레길 → 태풍 → 흑돼지."}'::jsonb, '{"en":"Jeju Island","ko":"제주도"}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, '{"kind":"airport","code":"CJU","name":{"en":"Jeju International Airport","ko":"제주국제공항"}}'::jsonb, 4, 5, 3, '{"solo":3,"couple":4,"friends":5,"group":5}'::jsonb, '{"solo":{"en":"Without a car, use Jeju''s express buses and walk the Olle trails – guesthouses are social.","ko":"차가 없다면 제주 급행버스를 타고 올레길을 걸어 보세요. 게스트하우스에선 사람들과 어울리기 좋아요."},"couple":{"en":"Rent a small EV and drive the coastal road at sunset.","ko":"소형 전기차를 빌려 해 질 녘 해안도로를 달려 보세요."},"friends":{"en":"Split a rental car and a pension with a BBQ terrace.","ko":"렌터카와 바비큐 테라스가 있는 펜션을 함께 나눠 쓰세요."},"group":{"en":"Rent a van with a driver or book a pension villa for the whole group.","ko":"기사 포함 승합차를 빌리거나 단체가 함께 묵을 펜션 독채를 예약하세요."}}'::jsonb, 800000, 'mountain', 'base', null, true, 4, 4),
